from typing import List

class Solution:
    def flipAndInvertImage(self, image: List[List[int]]) -> List[List[int]]:
        n = len(image)
        for row in image:
            for c in range((n + 1) // 2):
                row[c], row[n - 1 - c] = 1 - row[n - 1 - c], 1 - row[c]
        return image

class Solution {
public:
    vector<vector<int>> flipAndInvertImage(vector<vector<int>>& image) {
        int n = image.size();
        for (auto& row : image) {
            for (int c = 0; c < (n + 1) / 2; c++) {
                int tmp = 1 - row[c];
                row[c] = 1 - row[n - 1 - c];
                row[n - 1 - c] = tmp;
            }
        }
        return image;
    }
};

class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        int n = image.length;
        for (int[] row : image) {
            for (int c = 0; c < (n + 1) / 2; c++) {
                int tmp = 1 - row[c];
                row[c] = 1 - row[n - 1 - c];
                row[n - 1 - c] = tmp;
            }
        }
        return image;
    }
}

var flipAndInvertImage = function(image) {
    const n = image.length;
    for (const row of image) {
        for (let c = 0; c < Math.floor((n + 1) / 2); c++) {
            const tmp = 1 - row[c];
            row[c] = 1 - row[n - 1 - c];
            row[n - 1 - c] = tmp;
        }
    }
    return image;
};
